import { isString } from '@nestjs/common/utils/shared.utils.js';
import 'reflect-metadata';
import { Resolver } from '../enums/resolver.enum.js';
import { UndefinedReturnTypeError } from '../schema-builder/errors/undefined-return-type.error.js';
import { LazyMetadataStorage } from '../schema-builder/storages/lazy-metadata.storage.js';
import { TypeMetadataStorage } from '../schema-builder/storages/type-metadata.storage.js';
import { reflectTypeFromMetadata } from '../utils/reflection.utilts.js';
import { addResolverMetadata } from './resolvers.utils.js';
/**
 * Query handler (method) Decorator. Routes specified query to this method.
 *
 * @publicApi
 */
export function Query(nameOrType, options = {}) {
    return (target, key, descriptor) => {
        const name = isString(nameOrType)
            ? nameOrType
            : (options && options.name) || undefined;
        addResolverMetadata(Resolver.QUERY, name, target, key, descriptor);
        LazyMetadataStorage.store(target.constructor, () => {
            if (!nameOrType || isString(nameOrType)) {
                throw new UndefinedReturnTypeError(Query.name, key);
            }
            const { typeFn, options: typeOptions } = reflectTypeFromMetadata({
                metadataKey: 'design:returntype',
                prototype: target,
                propertyKey: key,
                explicitTypeFn: nameOrType,
                typeOptions: options || {},
            });
            const metadata = {
                methodName: key,
                schemaName: options.name || key,
                target: target.constructor,
                typeFn,
                returnTypeOptions: typeOptions,
                description: options.description,
                deprecationReason: options.deprecationReason,
                complexity: options.complexity,
            };
            TypeMetadataStorage.addQueryMetadata(metadata);
        });
    };
}
